CREATE TABLE superhero AS
SELECT id, height_cm, weight_kg, publisher_id, race_id, alignment_id, eye_colour_id, gender_id, hair_colour_id, skin_colour_id FROM colour;

CREATE TABLE superpower AS
SELECT id, power_name FROM superpower;

CREATE TABLE hero_attribute AS
SELECT hero_id, attribute_id, attribute_value, attribute_name, attribute_type FROM attribute;

CREATE TABLE color AS
SELECT id, colour, height_cm, weight_kg, publisher_id, race_id, alignment_id, eye_colour_id, gender_id, hair_colour_id, skin_colour_id FROM colour;

CREATE TABLE hero POWER (id INTEGER not null primary key, power_name TEXT default NULL)

